import React, { useState, useEffect } from "react";
import axios from "axios";
import "../styles/main.css";
import toast from "react-hot-toast";

export default function FeeStructure() {
  const [structure, setStructure] = useState(null);
  const [admissionNo, setAdmissionNo] = useState("");
  const [student, setStudent] = useState(null);
  const [loading, setLoading] = useState(false);

  // 1️⃣ Load overall fee structure
  useEffect(() => {
    axios.get("/api/fees")
      .then(res => setStructure(res.data.data))
      .catch(() => toast.error("Failed to load fee structure"));
  }, []);

  // 2️⃣ When user enters admission number, verify
  const checkAdmission = async () => {
    if (!admissionNo.trim()) return toast.error("Enter Admission No");
    setLoading(true);
    try {
      const res = await axios.get(`/api/fees/student/${admissionNo.trim()}`);
      if (res.data.success) {
        setStudent(res.data.data.student);
        toast.success("Student found!");
      }
    } catch {
      toast.error("Admission not found");
      setStudent(null);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fee-structure-container">
      <h2>Fee Structure ({structure?.academicYear})</h2>
      <div
        className="notes"
        dangerouslySetInnerHTML={{ __html: structure?.notes }}
      ></div>

      <table className="fee-table">
        <thead>
          <tr><th>Particulars</th><th>Amount (₹)</th></tr>
        </thead>
        <tbody>
          {structure?.items?.map((it, i) => (
            <tr key={i}>
              <td>{it.title}</td>
              <td>{it.amount}</td>
            </tr>
          ))}
          <tr className="total-row">
            <td><strong>Total</strong></td>
            <td>
              ₹{structure?.items?.reduce((a, b) => a + (b.amount || 0), 0)}
            </td>
          </tr>
        </tbody>
      </table>

      {/* 3️⃣ Admission check input */}
      <div className="check-admission">
        <h3>Already Admitted?</h3>
        <input
          type="text"
          placeholder="Enter your Admission No (e.g. KV-668272)"
          value={admissionNo}
          onChange={(e) => setAdmissionNo(e.target.value)}
        />
        <button disabled={loading} onClick={checkAdmission}>
          {loading ? "Checking..." : "Verify Admission"}
        </button>
      </div>

      {/* 4️⃣ Only show Pay Fee if student exists */}
      {student && (
        <div className="fee-actions">
          <p>
            Welcome, <strong>{student.studentName}</strong> (
            {student.admissionNo})
          </p>
          <button
            className="pay-btn"
            onClick={() =>
              window.location.href = `/fees?admissionNo=${student.admissionNo}`
            }
          >
            Pay School Fee
          </button>
        </div>
      )}
    </div>
  );
}
